
import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';


@Component({
  selector: 'app-mobile-profile-step',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './mobile-profile-step.html',
  styleUrl: './mobile-profile-step.css',
})
export class MobileProfileStep {

  constructor(private router: Router) {}

  profile = {

    fullName: 'Pravin Kalyanrao Bongane',

    dob: '04-04-1993',

    mobile: '9637999490',

    gender: 'Male',

    abhaNumber: '91-2656-8717-7832',

    abhaAddress: 'pravin49991_04@abdm',

    address: 'Pokhari, Bid, Maharashtra',

    photo: 'data:image/png;base64,' + '',

    // photo: 'assets/images/profile.png',

    // card: 'assets/images/abha-card.png'

    card: 'data:image/png;base64,' + '',

  };


  zoom = 1;

  rotation = 0;

  get transform() {

    return `
        scale(${this.zoom})
        rotate(${this.rotation}deg)
    `;

  }

  zoomIn(){

      this.zoom += 0.2;

  }

  zoomOut(){

      if(this.zoom > 0.4){

          this.zoom -= 0.2;

      }

  }

  rotate(){

      this.rotation += 90;

  }


  downloadCard(){

      console.log('Download');

      const link = document.createElement('a');

      link.href = this.profile.card;

      link.download = 'ABHA_Card.png';

      link.click();

  }

  printCard(){

    const win = window.open('');

    win!.document.write(`
        <img src="${this.profile.card}" style="width:100%">
    `);

    win!.print();

}

  finish(){

      console.log('Finish');

      this.router.navigate(['/abha/create']);

  }

}